function factList(p){
  const items=[
    ["Treatment time",p.facts.time],["Comfort / anesthesia",p.facts.comfort],["Typical downtime",p.facts.downtime],
    ["When changes may appear",p.facts.visible],["How long results may last",p.facts.duration],["Treatments commonly considered",p.facts.treatments]
  ];
  return items.map(([k,v])=>`<div class="fact"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join("");
}

function schema(p){
  const faq=p.faqs.map(([q,a])=>({"@type":"Question",name:q,acceptedAnswer:{"@type":"Answer",text:a}}));
  return JSON.stringify([
    {"@context":"https://schema.org","@type":"MedicalWebPage","name":`${p.title} Treatment Guide | Identity Aesthetics`,"url":`${base}treatment-${p.slug}.html`,"description":p.summary,"dateModified":"2026-07-30","about":{"@type":"MedicalProcedure","name":p.title},"audience":{"@type":"Patient"}},
    {"@context":"https://schema.org","@type":"FAQPage","mainEntity":faq},
    {"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":base},{"@type":"ListItem","position":2,"name":"Treatment Library","item":`${base}treatments.html`},{"@type":"ListItem","position":3,"name":p.title,"item":`${base}treatment-${p.slug}.html`}]}
  ]).replace(/</g,"\\u003c");
}

function render(p){
  const officeOnly=/in-office only|in-office\./i.test(p.availability) && !/telehealth may|telehealth can/i.test(p.availability);
  const teleEligible=/may be available in-office or by telehealth|Available in-office and by telehealth/i.test(p.availability);
  const setting=teleEligible?"In-office + eligible telehealth":"In-office treatment";
  const src=p.sources.map(([name,url])=>`<li><a href="${esc(url)}" target="_blank" rel="noopener">${esc(name)}</a></li>`).join("");
  const faq=p.faqs.map(([q,a])=>`<details><summary>${esc(q)}</summary><div class="a">${esc(a)}</div></details>`).join("");
  const process=p.process.map((x,i)=>`<div class="step"><h3>${["Evaluate","Plan & treat","Review & follow up"][i]||`Step ${i+1}`}</h3><p>${esc(x)}</p></div>`).join("");
  return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(p.title)} in Greater Houston | Identity Aesthetics</title>
<meta name="description" content="${esc(`${p.title}: candidacy, treatment process, downtime, results, risks, alternatives, pricing and booking at Identity Aesthetics.`)}">
<link rel="canonical" href="${base}treatment-${p.slug}.html">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Jost:ital,wght@0,300;0,400;0,500;1,300&display=swap" rel="stylesheet">
<link rel="stylesheet" href="treatment-page.css"><link rel="stylesheet" href="language-toggle.css"><link rel="stylesheet" href="site-enhancements.css"><script type="application/ld+json">${schema(p)}</script></head><body>
${nav()}<main>
<section class="hero"><div class="wrap"><p class="crumb"><a href="index.html">Home</a> / <a href="treatments.html">Treatment Library</a> / ${esc(p.title)}</p><div class="hero-grid"><div><span class="eyebrow">${esc(p.category)}</span><h1>${esc(p.title)}</h1><p class="lead">${esc(p.kicker)}. A clear, evidence-aware guide to candidacy, treatment, recovery, limitations and next steps.</p><div class="cta"><a class="btn btn-gold" href="${booking}" target="_blank" rel="noopener">Book a Consultation</a>${teleEligible?'<a class="btn btn-line" href="telehealth.html">Explore Telehealth</a>':'<a class="btn btn-line" href="treatments.html">View All Treatments</a>'}</div><div class="review-chip">Evidence reviewed ${reviewed}</div></div><dl class="quick"><div><b>Setting</b><span>${esc(setting)}</span></div><div><b>Pricing</b><span>${/^\$|^From/.test(p.pricing)?esc(p.pricing.split(".")[0]):"Consultation required"}</span></div><div><b>Provider review</b><span>Individualized</span></div></dl></div></div></section>
<section><div class="wrap answer"><div><span class="eyebrow">The short answer</span><h2>What is ${esc(p.title)}?</h2><p>${esc(p.summary)}</p></div><div class="answer-card"><h3>Concerns it may address</h3><ul>${p.concerns.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div></div></section>
<section class="alt"><div class="wrap"><div class="section-head"><span class="eyebrow">Candidacy</span><h2>Who may—or may not—be a candidate</h2></div><div class="grid g2"><article class="card"><h3>Who may be considered</h3><p>${esc(p.candidate)}</p></article><article class="card caution"><h3>When treatment may not be appropriate</h3><p>${esc(p.avoid)}</p></article></div></div></section>
<section><div class="wrap"><div class="section-head"><span class="eyebrow">At a glance</span><h2>Treatment facts</h2><p>These are practical planning ranges, not promises. Your consultation determines the exact plan.</p></div><dl class="facts">${factList(p)}</dl></div></section>
<section class="alt"><div class="wrap"><div class="section-head"><span class="eyebrow">Your visit</span><h2>What happens during treatment</h2></div><div class="grid g3 steps">${process}</div></div></section>
<section><div class="wrap"><div class="section-head"><span class="eyebrow">Informed choice</span><h2>Important risks, limitations and alternatives</h2></div><div class="grid g2"><article class="card caution"><h3>Risks &amp; limitations</h3><p>${esc(p.risks)}</p></article><article class="card"><h3>Alternatives to discuss</h3><ul>${p.alternatives.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></article></div></div></section>
<section class="alt"><div class="wrap answer"><div><span class="eyebrow">Clinical judgment</span><h2>Why provider experience matters</h2><p>${esc(p.provider)}</p></div><div class="answer-card"><h3>Identity Aesthetics approach</h3><ul><li>Diagnosis and anatomy before a product or device</li><li>Conservative planning with candid limitations</li><li>Licensed-provider supervision and complication readiness</li><li>In-office and telehealth boundaries stated clearly</li></ul></div></div></section>
<section><div class="wrap"><div class="setting"><div><span class="eyebrow">Access &amp; cost</span><h2>In-office versus telehealth</h2><p>${esc(p.availability)}</p><p><strong>Pricing:</strong> ${esc(p.pricing)}</p></div><div class="cta"><a class="btn btn-gold" href="${booking}" target="_blank" rel="noopener">Book a Consultation</a>${teleEligible?'<a class="btn btn-line" href="telehealth.html">Telehealth Details</a>':'<a class="btn btn-line" href="locations.html">View Locations</a>'}</div></div></div></section>
${p.slug==="glo2facial"?'<section class="alt"><div class="wrap"><div class="setting"><div><span class="eyebrow">Choose your protocol</span><h2>Explore every Glo2Facial OxyPod</h2><p>Compare the official treatment options, ingredients and cosmetic goals in Identity Aesthetics’ luxury Glo2Facial guide.</p></div><div class="cta"><a class="btn btn-gold" href="glo2facial-treatments.html">View Treatment Options</a></div></div></div></section>':""}
${p.slug==="physician-supervised-peptide-therapy"?'<section class="alt"><div class="wrap"><div class="setting"><div><span class="eyebrow">Go deeper</span><h2>Visit the Peptide Education Center</h2><p>Review FDA-approved peptide medicines, investigational compounds, sourcing safeguards, evidence grading and individual peptide guides.</p></div><div class="cta"><a class="btn btn-gold" href="peptide-education.html">Open Peptide Education</a></div></div></div></section>':""}
<section class="alt"><div class="wrap faq"><div class="section-head"><span class="eyebrow">Common questions</span><h2>${esc(p.title)} FAQ</h2></div>${faq}</div></section>
<section><div class="wrap"><div class="sources"><h2>Sources &amp; medical review</h2><ol>${src}</ol><p class="editorial"><strong>Medical-content evidence review:</strong> ${reviewed}. Content is written for patient education and structured from current primary regulatory, labeling and professional sources. It has not been individualized to your medical history. Product labeling and guidance can change; a licensed Identity Aesthetics provider confirms current suitability, informed consent and treatment details before care.</p></div></div></section>
<section class="band"><div class="wrap"><span class="eyebrow">Your next step</span><h2>Make an informed plan</h2><p>Bring your goals, questions, medication list and prior treatment history. We will help you decide whether ${esc(p.title)}—or an alternative—makes sense.</p><div class="cta"><a class="btn btn-gold" href="${booking}" target="_blank" rel="noopener">Book a Consultation</a><a class="btn btn-line" href="tel:713-268-6963">Call 713-BOTOX-ME</a></div></div></section>
</main>${footer()}</body></html>`;
}

